import { GithubStorageService } from '../services/github/github_storage_service'
import { githubAuthService } from '../services/github/github_auth_service'
import { LocalGitStorageService } from '../services/data/local_git_storage_service'
import { RemoteControlStorageService } from '../services/data/remote_control_storage_service'
import type { ProjectReference, StorageService } from './data_types'

export const LAST_PROJECT_STORAGE_KEY = 'md2.lastProject'

export type StorageType = 'github' | 'github-readonly' | 'local' | 'remote'

export interface LastProject {
    project: ProjectReference
    storageType: StorageType
}

const STORAGE_TYPES: StorageType[] = ['github', 'github-readonly', 'local', 'remote']

function isProjectReference(value: unknown): value is ProjectReference {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false

    const project = value as Partial<ProjectReference>

    return typeof project.branch === 'string' && typeof project.id === 'string'
}

function isStorageType(value: unknown): value is StorageType {
    return typeof value === 'string' && STORAGE_TYPES.includes(value as StorageType)
}

function isLastProject(value: unknown): value is LastProject {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false

    const lastProject = value as Partial<LastProject>

    return isStorageType(lastProject.storageType) && isProjectReference(lastProject.project)
}

function discardLastProject() {
    window.localStorage.removeItem(LAST_PROJECT_STORAGE_KEY)
}

/** Create only the storage backend for the chosen source. GitHub requires an access token. */
export function createStorageService(storageType: StorageType, accessToken: string | null): StorageService {
    if (storageType === 'remote') {
        const storage = new RemoteControlStorageService()
        storage.init()

        return storage
    }

    if (storageType === 'github' || storageType === 'github-readonly') {
        const storage = new GithubStorageService(storageType === 'github-readonly')
        storage.init({
            accessToken: accessToken ?? '',
            onUnauthorized: () => githubAuthService.handleUnauthorized(),
        })

        return storage
    }

    const storage = new LocalGitStorageService()
    storage.init()

    return storage
}

export function readLastProject(): LastProject | null {
    const storedValue = window.localStorage.getItem(LAST_PROJECT_STORAGE_KEY)
    if (!storedValue) return null

    let parsedValue: unknown
    try {
        parsedValue = JSON.parse(storedValue)
    } catch {
        discardLastProject()

        return null
    }

    if (isLastProject(parsedValue)) return parsedValue

    discardLastProject()

    return null
}

export function writeLastProject(storageType: StorageType, project: ProjectReference) {
    window.localStorage.setItem(LAST_PROJECT_STORAGE_KEY, JSON.stringify({ project, storageType }))
}

export const RECENT_LOCAL_REPOSITORIES_STORAGE_KEY = 'md2.recentLocalRepositories'
export const MAX_RECENT_LOCAL_REPOSITORIES = 5

function isRecentRepositoryList(value: unknown): value is string[] {
    return Array.isArray(value) && value.every((path) => typeof path === 'string' && path.length > 0)
}

/** Read canonical local repository roots, newest first. */
export function readRecentLocalRepositories() {
    const storedValue = window.localStorage.getItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY)
    if (!storedValue) return []

    try {
        const parsedValue: unknown = JSON.parse(storedValue)
        if (isRecentRepositoryList(parsedValue)) return parsedValue.slice(0, MAX_RECENT_LOCAL_REPOSITORIES)
    } catch {
        // Invalid stored history is discarded below.
    }

    window.localStorage.removeItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY)

    return []
}

/** Record one successfully opened canonical root with Windows case-insensitive uniqueness. */
export function recordRecentLocalRepository(rootPath: string) {
    if (rootPath.length === 0) throw new Error('Local repository root path is required')

    const normalizedRoot = rootPath.toLowerCase()
    const recentRepositories = readRecentLocalRepositories()
        .filter((path) => path.toLowerCase() !== normalizedRoot)
    const nextRepositories = [rootPath, ...recentRepositories].slice(0, MAX_RECENT_LOCAL_REPOSITORIES)
    window.localStorage.setItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY, JSON.stringify(nextRepositories))

    return nextRepositories
}

export const REMOTE_CONTROL_ENDPOINT_KEY = 'md2.remoteControl.endpoint'

export interface RemoteControlConnectionSettings {
    endpoint: string
}

export function configureRemoteControlConnection(settings: RemoteControlConnectionSettings) {
    window.localStorage.setItem(REMOTE_CONTROL_ENDPOINT_KEY, settings.endpoint)
}

export function tryReadRemoteControlConnection(): RemoteControlConnectionSettings | null {
    const endpoint = window.localStorage.getItem(REMOTE_CONTROL_ENDPOINT_KEY)
    if (!endpoint) return null

    return { endpoint }
}

export function readRemoteControlConnection(): RemoteControlConnectionSettings {
    const endpoint = window.localStorage.getItem(REMOTE_CONTROL_ENDPOINT_KEY)
    if (!endpoint) throw new Error('Missing remote-control endpoint')

    return { endpoint }
}

import {
    LOCAL_STORAGE_KEYS,
    requireConfigEntry,
    type ConfigKey,
    type ConfigValues,
    type DesktopConfigValues,
} from './config_entries'
import { getElectronConfigBridge } from './electron_config_bridge'

export const REACT_CONFIG_STORAGE_KEY = 'md2.reactConfig'

type MergeConfigValue = (values: ConfigValues, key: ConfigKey, value: unknown) => ConfigValues

export function readStoredReactValues(): Partial<Record<ConfigKey, unknown>> {
    const raw = window.localStorage.getItem(REACT_CONFIG_STORAGE_KEY)
    if (!raw) return {}

    try {
        const parsed = JSON.parse(raw) as unknown

        return parsed && typeof parsed === 'object' ? (parsed as Partial<Record<ConfigKey, unknown>>) : {}
    } catch {
        return {}
    }
}

export function writeStoredReactValues(values: ConfigValues) {
    const stored: Partial<Record<ConfigKey, unknown>> = {}
    for (const key of LOCAL_STORAGE_KEYS) stored[key] = values[key]

    window.localStorage.setItem(REACT_CONFIG_STORAGE_KEY, JSON.stringify(stored))
}

export function mergeStoredReactValues(values: ConfigValues, mergeValue: MergeConfigValue): ConfigValues {
    let nextValues = values
    const stored = readStoredReactValues()

    for (const key of LOCAL_STORAGE_KEYS) {
        if (stored[key] === undefined) continue

        try {
            nextValues = mergeValue(nextValues, key, stored[key])
        } catch {
            // ignore invalid persisted value, keep the default
        }
    }

    return nextValues
}

/** Read the startup-splash preference straight from storage, for use before the config service initializes. */
export function readStartupSplashPreference(): boolean {
    const stored = readStoredReactValues()['react.showStartupSplash']

    return typeof stored === 'boolean' ? stored : (requireConfigEntry('react.showStartupSplash').defaultValue as boolean)
}

export function readDesktopConfigFromBridge(): Partial<DesktopConfigValues> | null {
    return getElectronConfigBridge()?.getDesktopConfig() ?? null
}

export function writeDesktopConfigToBridge(values: DesktopConfigValues) {
    void getElectronConfigBridge()?.setDesktopConfig(values)
}

import { useCallback, useMemo, useState } from 'react'
import type { PaletteMode } from '@mui/material'
import {
    DEFAULT_COLOR_SCHEME,
    DEFAULT_MARKDOWN_STYLE_PRESET,
    MARKDOWN_STYLE_PRESETS,
    cloneMarkdownStyleConfig,
    isColorSchemeConfig,
    isMarkdownStyleConfig,
    isMarkdownStyleName,
    type ColorSchemeConfig,
    type MarkdownStyleConfig,
    type MarkdownStyleName,
    type MarkdownStylePresetName,
} from './theme_config'

export const THEME_MODE_STORAGE_KEY = 'md2.themeMode'
export const COLOR_SCHEME_STORAGE_KEY = 'md2.colorScheme'
export const MARKDOWN_STYLE_STORAGE_KEY = 'md2.markdownStyle'
export const CUSTOM_MARKDOWN_STYLE_STORAGE_KEY = 'md2.customMarkdownStyle'

/** The full set of persisted theme settings plus their mutators. */
export interface UseThemeSettingsResult {
    mode: PaletteMode
    colorScheme: ColorSchemeConfig
    markdownStyle: MarkdownStyleName
    markdownStyleConfig: MarkdownStyleConfig
    toggleMode: () => void
    setColorScheme: (colorScheme: ColorSchemeConfig) => void
    setMarkdownStyle: (preset: MarkdownStylePresetName) => void
    setCustomMarkdownStyle: (markdownStyleConfig: MarkdownStyleConfig) => void
}

function isPaletteMode(value: string | null): value is PaletteMode {
    return value === 'light' || value === 'dark'
}

/** Resolve the initial palette mode from storage, falling back to the OS preference. */
function readInitialMode(): PaletteMode {
    const storedMode = window.localStorage.getItem(THEME_MODE_STORAGE_KEY)
    if (isPaletteMode(storedMode)) return storedMode

    const prefersDark = window.matchMedia?.('(prefers-color-scheme: dark)').matches
    return prefersDark ? 'dark' : 'light'
}

/** Resolve the initial color scheme from storage, falling back to the default scheme. */
function readInitialColorScheme(): ColorSchemeConfig {
    const stored = window.localStorage.getItem(COLOR_SCHEME_STORAGE_KEY)
    if (stored === null) return DEFAULT_COLOR_SCHEME

    try {
        const parsed = JSON.parse(stored)
        if (isColorSchemeConfig(parsed)) return parsed
    } catch {
        return DEFAULT_COLOR_SCHEME
    }

    return DEFAULT_COLOR_SCHEME
}

interface InitialMarkdownStyle {
    config: MarkdownStyleConfig
    name: MarkdownStyleName
}

function readCustomMarkdownStyle(): MarkdownStyleConfig | null {
    const stored = window.localStorage.getItem(CUSTOM_MARKDOWN_STYLE_STORAGE_KEY)
    if (stored === null) return null

    try {
        const parsed = JSON.parse(stored)
        return isMarkdownStyleConfig(parsed) ? parsed : null
    } catch {
        return null
    }
}

/** Resolve the initial markdown style from storage, falling back to the default preset. */
function readInitialMarkdownStyle(): InitialMarkdownStyle {
    const stored = window.localStorage.getItem(MARKDOWN_STYLE_STORAGE_KEY)
    if (isMarkdownStyleName(stored)) {
        if (stored !== 'custom') return { config: MARKDOWN_STYLE_PRESETS[stored], name: stored }

        const customConfig = readCustomMarkdownStyle()
        if (customConfig) return { config: customConfig, name: stored }
    }

    return { config: MARKDOWN_STYLE_PRESETS[DEFAULT_MARKDOWN_STYLE_PRESET], name: DEFAULT_MARKDOWN_STYLE_PRESET }
}

/**
 * Manage the persisted theme settings â€” palette mode, color scheme and markdown
 * style selection â€” mirroring each change into localStorage so choices survive
 * restarts. This is the single source of truth consumed by the theme provider.
 */
export function useThemeSettings(): UseThemeSettingsResult {
    const [mode, setMode] = useState<PaletteMode>(readInitialMode)
    const [colorScheme, setColorSchemeState] = useState<ColorSchemeConfig>(readInitialColorScheme)
    const [initialMarkdownStyle] = useState<InitialMarkdownStyle>(readInitialMarkdownStyle)
    const [markdownStyle, setMarkdownStyleState] = useState<MarkdownStyleName>(initialMarkdownStyle.name)
    const [markdownStyleConfig, setMarkdownStyleConfig] = useState<MarkdownStyleConfig>(initialMarkdownStyle.config)

    const toggleMode = useCallback(() => {
        setMode((currentMode) => {
            const nextMode: PaletteMode = currentMode === 'light' ? 'dark' : 'light'
            window.localStorage.setItem(THEME_MODE_STORAGE_KEY, nextMode)
            return nextMode
        })
    }, [])

    const setColorScheme = useCallback((nextColorScheme: ColorSchemeConfig) => {
        window.localStorage.setItem(COLOR_SCHEME_STORAGE_KEY, JSON.stringify(nextColorScheme))
        setColorSchemeState(nextColorScheme)
    }, [])

    const setMarkdownStyle = useCallback((preset: MarkdownStylePresetName) => {
        window.localStorage.setItem(MARKDOWN_STYLE_STORAGE_KEY, preset)
        setMarkdownStyleState(preset)
        setMarkdownStyleConfig(MARKDOWN_STYLE_PRESETS[preset])
    }, [])

    const setCustomMarkdownStyle = useCallback((nextMarkdownStyleConfig: MarkdownStyleConfig) => {
        const config = cloneMarkdownStyleConfig(nextMarkdownStyleConfig)
        window.localStorage.setItem(MARKDOWN_STYLE_STORAGE_KEY, 'custom')
        window.localStorage.setItem(CUSTOM_MARKDOWN_STYLE_STORAGE_KEY, JSON.stringify(config))
        setMarkdownStyleState('custom')
        setMarkdownStyleConfig(config)
    }, [])

    return useMemo(
        () => ({
            mode,
            colorScheme,
            markdownStyle,
            markdownStyleConfig,
            toggleMode,
            setColorScheme,
            setMarkdownStyle,
            setCustomMarkdownStyle,
        }),
        [
            mode,
            colorScheme,
            markdownStyle,
            markdownStyleConfig,
            toggleMode,
            setColorScheme,
            setMarkdownStyle,
            setCustomMarkdownStyle,
        ],
    )
}

import { GithubApiClient } from '../../auth/github_api_client'
import type { ProjectReference } from '../../data/data_types'
import type { GithubStorageDependencies, NormalizedGithubTreeEntry, PendingCommitHead } from './github_storage_types'
import { createPendingHeadKey } from './github_storage_types'

const PENDING_COMMIT_HEADS_STORAGE_KEY = 'md2.github.pendingCommitHeads'
const PENDING_CONFLICT_MESSAGE = 'Unpushed GitHub commits conflict with the current branch. Discard pending commits or resolve the branch manually before opening this project.'

function readStoredPendingCommitHeads() {
    const storedValue = window.localStorage.getItem(PENDING_COMMIT_HEADS_STORAGE_KEY)
    if (!storedValue) return new Map<string, PendingCommitHead>()

    const parsedValue = JSON.parse(storedValue) as Record<string, PendingCommitHead>

    return new Map(Object.entries(parsedValue))
}

function writeStoredPendingCommitHeads(pendingCommitHeads: Map<string, PendingCommitHead>) {
    const storedValue = Object.fromEntries(pendingCommitHeads)

    if (Object.keys(storedValue).length === 0) {
        window.localStorage.removeItem(PENDING_COMMIT_HEADS_STORAGE_KEY)

        return
    }

    window.localStorage.setItem(PENDING_COMMIT_HEADS_STORAGE_KEY, JSON.stringify(storedValue))
}

export function readStoredPendingCommitHead(project: ProjectReference) {
    return readStoredPendingCommitHeads().get(createPendingHeadKey(project))
}

export function deleteStoredPendingCommitHead(project: ProjectReference) {
    const storedPendingHeads = readStoredPendingCommitHeads()
    storedPendingHeads.delete(createPendingHeadKey(project))
    writeStoredPendingCommitHeads(storedPendingHeads)
}

export class GithubPendingCommitConflictError extends Error {
    project: ProjectReference

    constructor(project: ProjectReference) {
        super(PENDING_CONFLICT_MESSAGE)
        this.project = project
    }
}

export class GithubStorageContext {
    private accessToken: string | null = null
    private activeProject: ProjectReference | null = null

    apiClient: GithubApiClient | null = null
    pendingCommitHeads = new Map<string, PendingCommitHead>()
    projectTreeEntriesByHead = new Map<string, NormalizedGithubTreeEntry[]>()
    recursiveTreeEntriesBySha = new Map<string, Map<string, string>>()

    init(dependencies: GithubStorageDependencies) {
        this.accessToken = dependencies.accessToken
        this.activeProject = null
        this.apiClient = new GithubApiClient(dependencies)
        this.pendingCommitHeads = readStoredPendingCommitHeads()
        this.projectTreeEntriesByHead = new Map()
        this.recursiveTreeEntriesBySha = new Map()
    }

    getAccessToken() {
        if (this.accessToken === null) throw new Error('GitHub storage access token is not initialized')

        return this.accessToken
    }

    getApiClient() {
        if (!this.apiClient) throw new Error('GitHub storage API client is not initialized')

        return this.apiClient
    }

    getCommitProject() {
        if (!this.activeProject) throw new Error('Cannot commit before a GitHub project is loaded')

        return this.activeProject
    }

    requireGithubProject(project: ProjectReference) {
        if (!project.owner) throw new Error('Missing GitHub project owner')
        if (!project.repository) throw new Error('Missing GitHub project repository')

        this.activeProject = project
    }

    writePendingCommitHeads() {
        writeStoredPendingCommitHeads(this.pendingCommitHeads)
    }
}

